/* DeepSeek's loader lanes block in pread and therefore do not need permanent
 * core reservations.  What does hurt is putting the barriered matvec team on
 * both SMT siblings.  Use the physical-core tuner shared by the other engines;
 * on this WSL host it selects the measured optimum, 6 instead of 12 threads.
 * OMP_NUM_THREADS remains an unconditional user override. */
static void v4_stream_tune_threads(void) {
    coli_omp_tune_threads("deepseek-stream");
}

#ifdef COLI_V4_EXPERIMENTAL_BLOCK_OTHER_PROFILE
static double coli_v4_profile_seconds[4];
static unsigned long long coli_v4_profile_calls[4];

double coli_v4_block_profile_now(void) {
    struct timespec value;
    clock_gettime(CLOCK_MONOTONIC, &value);
    return (double)value.tv_sec + (double)value.tv_nsec * 1e-9;
}

void coli_v4_block_profile_add(int kind, double seconds) {
    if (kind < 0 || kind >= 4) return;
    #pragma omp atomic update
    coli_v4_profile_seconds[kind] += seconds;
    #pragma omp atomic update
    coli_v4_profile_calls[kind]++;
}

static void coli_v4_block_profile_report(void) {
    static const char *names[4] = {
        "moe_total", "gate_decode", "loader_start", "loader_wait"
    };
    if (!getenv("V4_PROFILE")) return;
    for (int i = 0; i < 4; i++)
        fprintf(stderr, "v4_profile %s=%.6fs calls=%llu\n", names[i],
                coli_v4_profile_seconds[i], coli_v4_profile_calls[i]);
}

__attribute__((constructor))
static void coli_v4_block_profile_register(void) {
    atexit(coli_v4_block_profile_report);
}
#endif


